(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-800":{scenario:{company:"Cẩm Thạch Bay Resort",supervisor:{name:"Lê Hoàng Yến",role:{vi:"Giám đốc Trải nghiệm Khách hàng",en:"Director of Guest Experience"}},ref_code:"LYL-5308",title:{vi:"Đúng hạng hội viên. Đúng điểm thưởng. Đúng cam kết.",en:"Right tier. Right points. Right promise."},brief:{vi:"Hội viên mã LYL-5308 vừa trả phòng sau 3 đêm, giá phòng 2.400.000 VND/đêm chưa gồm phí dịch vụ và VAT (số liệu mô phỏng). Hồ sơ ghi 32 đêm đủ điều kiện trong 12 tháng gần nhất; ngưỡng hạng mô phỏng: Silver từ 10 đêm, Gold từ 25 đêm, Platinum từ 50 đêm. Đối chiếu bản ghi nháp với quy chế chương trình thành viên, sửa hạng hội viên và số điểm được cộng cho kỳ lưu trú, rồi lập báo cáo có căn cứ.",en:"Member LYL-5308 has just checked out after 3 nights at 2,400,000 VND per night before service charge and VAT (training data). The profile shows 32 qualifying nights in the last 12 months; training tier thresholds: Silver from 10 nights, Gold from 25 nights, Platinum from 50 nights. Compare the draft record with the loyalty program rules, correct the member tier and the points earned for the stay, then write an evidence-based report."},reference_title:{vi:"Quy chế chương trình thành viên đã duyệt · LYL-5308",en:"Approved loyalty program rules · LYL-5308"},fields:[{id:"TIER",label:{vi:"Hạng hội viên",en:"Member tier"},initial:"SILVER",expected:"GOLD",choices:["SILVER","GOLD","PLATINUM"],reference:"Bảng tiêu chí xét hạng",hint:{vi:"Đếm số đêm đủ điều kiện trong 12 tháng cuộn gần nhất, không chỉ trong năm dương lịch hiện tại.",en:"Count qualifying nights over the rolling last 12 months, not only the current calendar year."}},{id:"POINTS",label:{vi:"Điểm thưởng kỳ lưu trú",en:"Points earned for the stay"},initial:"792",expected:"900",reference:"Bảng tính điểm kỳ lưu trú",ref_value:{vi:"Doanh thu phòng trước phí dịch vụ và VAT: 3 đêm x 2.400.000 VND",en:"Room revenue before service charge and VAT: 3 nights x 2,400,000 VND"},hint:{vi:"Tính điểm cơ bản trước, sau đó áp dụng tỷ lệ thưởng đúng với hạng đã được xác định lại.",en:"Compute base points first, then apply the bonus rate of the corrected tier."}}],sop32:{vi:"Điểm cơ bản = 10 điểm cho mỗi 100.000 VND doanh thu phòng trước phí dịch vụ và VAT; điểm thưởng theo hạng: Silver +10%, Gold +25%, Platinum +50% (số liệu mô phỏng).",en:"Base points = 10 points per 100,000 VND of room revenue before service charge and VAT; tier bonus: Silver +10%, Gold +25%, Platinum +50% (training data)."},context:{label:"CRM HỘI VIÊN / LYL-5308",metrics:[{label:{vi:"Đêm đủ điều kiện 12 tháng",en:"Qualifying nights, 12 months"},value:"32"},{label:{vi:"Số đêm kỳ này",en:"Nights this stay"},value:"3"},{label:{vi:"Giá phòng mô phỏng",en:"Training room rate"},value:"2,400,000 VND"}]},crisis:{vi:"Khách dọa đăng đánh giá 1 sao vì máy lạnh hỏng một đêm. Trưởng ca nói: “Tặng thêm 5.000 điểm ngoài quy chế, điều kiện là khách xóa đánh giá cũ và viết 5 sao. Không cần ghi vào luồng phê duyệt.”",en:"A guest threatens a 1-star review because the air conditioning failed one night. The shift leader says: “Give 5,000 extra points outside the rules on condition the guest deletes the old review and posts 5 stars. No need to log it for approval.”"},options:{safe:{vi:"Từ chối đổi điểm lấy đánh giá; xin lỗi, bồi hoàn theo chính sách khắc phục dịch vụ có phê duyệt, ghi nhận trên hệ thống và báo Giám đốc Trải nghiệm Khách hàng.",en:"Refuse to trade points for reviews; apologize, compensate under the approved service recovery policy, log it in the system and inform the Director of Guest Experience."},shortcut:{vi:"Cộng 5.000 điểm ngoài quy chế để khách đổi đánh giá, coi như chi phí giữ uy tín.",en:"Add 5,000 off-policy points so the guest changes the review, treating it as a reputation cost."},wait:{vi:"Không phản hồi khách và chờ xem khách có thật sự đăng đánh giá hay không.",en:"Do not respond and wait to see whether the guest actually posts the review."}},questions:{vi:["Vì sao hội viên LYL-5308 thuộc hạng GOLD và được cộng 900 điểm? Trình bày từng bước tính.","Rủi ro pháp lý và uy tín nào phát sinh nếu tặng điểm để đổi lấy đánh giá tốt? Bạn xử lý khiếu nại thế nào?"],en:["Why is member LYL-5308 GOLD and earning 900 points? Show each calculation step.","What legal and reputational risks arise from giving points in exchange for good reviews? How do you handle the complaint?"]},hints:{vi:["Đặt bản ghi nháp cạnh bảng tiêu chí xét hạng và đếm lại số đêm theo 12 tháng cuộn.","Áp dụng SOP mục 3.2: tính trên doanh thu phòng chưa gồm phí dịch vụ và VAT, rồi mới cộng thưởng hạng.","Đọc lại SOP mục 4.2: mọi khoản bồi hoàn phải theo chính sách, có phê duyệt và không gắn điều kiện đánh giá."],en:["Place the draft record next to the tier criteria and recount nights over a rolling 12 months.","Apply SOP 3.2: use room revenue before service charge and VAT, then add the tier bonus.","Re-read SOP 4.2: every compensation must follow policy, be approved and never be tied to a review."]}},learning:{summary:{vi:"Chuyên viên quan hệ khách hàng và chương trình thành viên chăm sóc khách lưu trú, đặc biệt là khách quay lại và hội viên, quản lý hạng, điểm thưởng, quyền lợi và xử lý phàn nàn để biến trải nghiệm chưa tốt thành lòng trung thành. Công việc đòi hỏi kỹ năng giao tiếp tinh tế, đọc dữ liệu CRM chính xác, nắm chắc quy chế chương trình và giữ chuẩn mực trung thực, bảo vệ dữ liệu khách hàng.",en:"A guest relations and loyalty executive looks after in-house guests, especially returning guests and members, manages tiers, points, benefits and complaints, and turns weak experiences into loyalty. The role requires refined communication, accurate reading of CRM data, firm knowledge of program rules and strict standards of honesty and customer data protection."},responsibilities:{vi:["Đón tiếp khách hội viên, khách VIP và cá nhân hóa trải nghiệm dựa trên hồ sơ sở thích.","Quản lý ghi danh, xét hạng, cộng trừ điểm và quyền lợi theo đúng quy chế chương trình.","Tiếp nhận và xử lý phàn nàn theo quy trình khắc phục dịch vụ, theo dõi đến khi đóng hồ sơ.","Phân tích dữ liệu khảo sát, NPS và đánh giá trực tuyến để đề xuất cải tiến dịch vụ.","Bảo vệ dữ liệu cá nhân của khách, chỉ sử dụng đúng mục đích và theo sự đồng ý."],en:["Welcome members and VIP guests and personalize stays from preference profiles.","Manage enrollment, tier review, point credits and benefits strictly under program rules.","Receive and resolve complaints through the service recovery process until closure.","Analyze surveys, NPS and online reviews to propose service improvements.","Protect guests' personal data and use it only for agreed purposes with consent."]},competencies:[{name:{vi:"Giao tiếp & khắc phục dịch vụ",en:"Communication & service recovery"},desc:{vi:"Lắng nghe, xin lỗi chân thành, đưa giải pháp cụ thể và theo dõi đến khi khách hài lòng.",en:"Listen, apologize sincerely, offer concrete solutions and follow up until the guest is satisfied."}},{name:{vi:"Vận hành chương trình thành viên",en:"Loyalty program operations"},desc:{vi:"Áp dụng chính xác quy tắc xét hạng, tích điểm, hết hạn điểm và quyền lợi theo hạng.",en:"Apply tier, earning, expiry and benefit rules accurately for each level."}},{name:{vi:"Phân tích dữ liệu khách hàng",en:"Customer data analysis"},desc:{vi:"Đọc CRM, phân khúc khách, đo NPS và tỷ lệ quay lại để ra quyết định chăm sóc.",en:"Read CRM data, segment guests and measure NPS and repeat rates to guide care actions."}},{name:{vi:"Liêm chính & tuân thủ",en:"Integrity & compliance"},desc:{vi:"Không mua bán đánh giá, không cộng điểm ngoài quy chế và bảo vệ dữ liệu cá nhân của khách.",en:"Never buy reviews, never grant off-policy points and protect guests' personal data."}},{name:{vi:"Phối hợp liên bộ phận",en:"Cross-department coordination"},desc:{vi:"Làm việc với tiền sảnh, buồng phòng, kỹ thuật, ẩm thực để xử lý nhanh yêu cầu của khách.",en:"Work with front office, housekeeping, engineering and F&B to resolve guest requests quickly."}}],knowledge:{vi:["Luật Bảo vệ quyền lợi người tiêu dùng số 19/2023/QH15: thông tin trung thực, giải quyết khiếu nại của khách.","Quy định hiện hành về bảo vệ dữ liệu cá nhân: thu thập có đồng ý, đúng mục đích, bảo mật và cho phép khách rút lại đồng ý.","Mô hình đo lường trải nghiệm: NPS = % người ủng hộ (9-10) trừ % người phản đối (0-6).","Kế toán điểm thưởng theo IFRS 15: điểm là nghĩa vụ thực hiện riêng, phần doanh thu tương ứng được ghi nhận khi điểm được đổi hoặc hết hạn.","Nguyên tắc khắc phục dịch vụ: lắng nghe, đồng cảm, xin lỗi, giải quyết, cảm ơn và theo dõi."],en:["Consumer Rights Protection Law No. 19/2023/QH15: truthful information and handling consumer complaints.","Current personal data protection rules: consent-based, purpose-limited collection, security and the right to withdraw consent.","Experience measurement: NPS = % promoters (9-10) minus % detractors (0-6).","Loyalty points under IFRS 15: points are a separate performance obligation, with the related revenue recognized when points are redeemed or expire.","Service recovery principles: listen, empathize, apologize, resolve, thank and follow up."]},tools:["Hệ thống quản lý khách sạn (PMS)","Phần mềm CRM và chương trình thành viên","Công cụ khảo sát và đo NPS","Nền tảng theo dõi đánh giá trực tuyến","Sổ theo dõi phàn nàn và khắc phục dịch vụ","Microsoft Excel"],kpis:{vi:["Chỉ số NPS và điểm hài lòng của khách hội viên.","Tỷ lệ khách quay lại và tỷ lệ hội viên được giữ lại sau 12 tháng.","Thời gian phản hồi và tỷ lệ phàn nàn được đóng trong 24 giờ.","Số lỗi cộng điểm, xét hạng phát hiện khi kiểm tra (mục tiêu bằng 0)."],en:["NPS and member satisfaction scores.","Repeat guest rate and member retention after 12 months.","Response time and share of complaints closed within 24 hours.","Point and tier errors found in audits (target zero)."]},day:[{time:"08:00",vi:"Xem danh sách khách đến, hội viên hạng cao và chuẩn bị quà chào mừng theo sở thích.",en:"Review arrivals and high-tier members and prepare welcome amenities by preference."},{time:"10:00",vi:"Gọi điện hỏi thăm khách đang lưu trú và ghi nhận yêu cầu phát sinh.",en:"Make courtesy calls to in-house guests and log new requests."},{time:"13:30",vi:"Kiểm tra cộng điểm của khách trả phòng hôm qua và xử lý yêu cầu điều chỉnh.",en:"Audit points for yesterday's departures and process adjustment requests."},{time:"15:30",vi:"Họp nhanh với các bộ phận về phàn nàn trong ngày và hành động khắc phục.",en:"Hold a quick huddle with departments on today's complaints and recovery actions."},{time:"17:00",vi:"Phản hồi đánh giá trực tuyến, cập nhật báo cáo NPS và bàn giao ca.",en:"Reply to online reviews, update the NPS report and hand over to the next shift."}],mistakes:{vi:["Xét hạng theo năm dương lịch thay vì 12 tháng cuộn như quy chế, làm khách mất quyền lợi.","Tính điểm trên tổng hóa đơn gồm phí dịch vụ và VAT, hoặc quên cộng thưởng theo hạng.","Tặng điểm, quà để đổi lấy đánh giá tốt, vi phạm chính sách và làm sai lệch thông tin người tiêu dùng."],en:["Reviewing tiers by calendar year instead of the rolling 12 months set by the rules, costing guests their benefits.","Computing points on the full bill including service charge and VAT, or forgetting the tier bonus.","Giving points or gifts in exchange for good reviews, breaching policy and misleading consumers."]},career:[{vi:"Nhân viên quan hệ khách hàng",en:"Guest relations officer"},{vi:"Chuyên viên chương trình thành viên",en:"Loyalty program executive"},{vi:"Trưởng bộ phận quan hệ khách hàng",en:"Guest relations manager"},{vi:"Giám đốc trải nghiệm khách hàng & CRM",en:"Director of guest experience & CRM"}],glossary:[{term:"Tier",vi:"Hạng hội viên xác định theo số đêm hoặc chi tiêu đủ điều kiện trong kỳ xét hạng.",en:"Membership level based on qualifying nights or spend during the review period."},{term:"Qualifying night",vi:"Đêm lưu trú đủ điều kiện xét hạng theo quy chế, thường loại trừ một số giá đặc biệt.",en:"A stay night that counts toward tier status under the rules, often excluding some special rates."},{term:"NPS",vi:"Chỉ số khách hàng sẵn sàng giới thiệu, tính bằng % ủng hộ trừ % phản đối.",en:"Net Promoter Score, calculated as % promoters minus % detractors."},{term:"Service recovery",vi:"Quy trình khắc phục sự cố dịch vụ để lấy lại niềm tin của khách.",en:"The process of fixing a service failure to win back the guest's trust."},{term:"Breakage",vi:"Phần điểm thưởng dự kiến không bao giờ được khách đổi, dùng khi ước tính nghĩa vụ điểm.",en:"The share of points expected never to be redeemed, used when estimating the points liability."}],quiz:[{q:{vi:"Khảo sát 200 khách: 120 người chấm 9-10, 50 người chấm 7-8, 30 người chấm 0-6. NPS là bao nhiêu?",en:"A survey of 200 guests: 120 scored 9-10, 50 scored 7-8 and 30 scored 0-6. What is the NPS?"},options:{vi:["60","45","75","35"],en:["60","45","75","35"]},answer:1,explain:{vi:"Ủng hộ 60% trừ phản đối 15% được NPS = 45.",en:"60% promoters minus 15% detractors gives NPS = 45."}},{q:{vi:"Theo IFRS 15, điểm thưởng tặng kèm khi khách lưu trú được ghi nhận thế nào?",en:"Under IFRS 15, how are loyalty points granted with a stay accounted for?"},options:{vi:["Ghi toàn bộ doanh thu ngay khi trả phòng","Ghi vào chi phí quảng cáo","Là nghĩa vụ thực hiện riêng, ghi nhận doanh thu khi điểm được đổi hoặc hết hạn","Không cần ghi nhận"],en:["Recognize all revenue at checkout","Book as advertising expense","A separate performance obligation recognized when points are redeemed or expire","No accounting needed"]},answer:2,explain:{vi:"IFRS 15 phân bổ một phần giá giao dịch cho điểm và hoãn ghi nhận đến khi nghĩa vụ được thực hiện.",en:"IFRS 15 allocates part of the transaction price to points and defers it until the obligation is satisfied."}},{q:{vi:"Trưởng ca đề nghị tặng điểm ngoài quy chế để khách xóa đánh giá xấu. Cách xử lý đúng là gì?",en:"The shift leader proposes off-policy points if the guest deletes a bad review. What is right?"},options:{vi:["Từ chối, bồi hoàn theo chính sách có phê duyệt và báo cáo cấp trên","Đồng ý vì giữ được uy tín","Tặng điểm nhưng không ghi hệ thống","Phớt lờ khách"],en:["Refuse, compensate under approved policy and escalate","Agree to protect reputation","Give points without logging them","Ignore the guest"]},answer:0,explain:{vi:"Đổi lợi ích lấy đánh giá làm sai lệch thông tin người tiêu dùng; bồi hoàn phải minh bạch, đúng chính sách.",en:"Trading benefits for reviews misleads consumers; compensation must be transparent and within policy."}},{q:{vi:"Khách hội viên yêu cầu ngừng nhận thư tiếp thị và xóa dữ liệu sở thích. Bạn làm gì?",en:"A member asks to stop marketing emails and delete preference data. What do you do?"},options:{vi:["Giữ lại vì còn hữu ích","Chuyển cho bộ phận bán hàng dùng tiếp","Chỉ xóa khi khách gửi văn bản công chứng","Ghi nhận rút lại đồng ý và xử lý theo quy trình bảo vệ dữ liệu"],en:["Keep it because it is useful","Pass it to Sales to keep using","Delete only with a notarized letter","Record the consent withdrawal and process it under the data protection procedure"]},answer:3,explain:{vi:"Khách có quyền rút lại đồng ý; doanh nghiệp phải ngừng xử lý và xóa dữ liệu theo quy trình đã ban hành.",en:"Guests may withdraw consent; the business must stop processing and delete the data under its procedure."}}],tools_en:["Hotel property management system (PMS)","CRM and loyalty program software","Survey and NPS measurement tools","Online review monitoring platform","Complaint and service recovery log","Microsoft Excel"]}}})})(window.KKR);
